WITH allowed AS MATERIALIZED (SELECT rel_path,source_version,predicate,value FROM facts WHERE line IS NULL AND item_key IS NULL AND namespace IN ('fixture')),c1 AS MATERIALIZED (SELECT * FROM (SELECT rel_path, line, item_key, source_version, namespace FROM facts WHERE predicate = 'fixture.kind' AND value = 'entry' AND line IS NULL AND item_key IS NULL) WHERE namespace IN (SELECT value FROM json_each('["fixture"]')) AND line IS NULL AND item_key IS NULL),c2 AS MATERIALIZED (SELECT * FROM (SELECT rel_path, line, item_key, source_version, namespace FROM facts WHERE predicate = 'fixture.key' AND value = 'al' AND line IS NULL AND item_key IS NULL) WHERE namespace IN (SELECT value FROM json_each('["fixture"]')) AND line IS NULL AND item_key IS NULL),c3 AS MATERIALIZED (SELECT * FROM (SELECT rel_path, line, item_key, source_version, namespace FROM facts WHERE predicate = 'fixture.key' AND instr(gilune_fold(value), 'al') = 1 AND line IS NULL AND item_key IS NULL) WHERE namespace IN (SELECT value FROM json_each('["fixture"]')) AND line IS NULL AND item_key IS NULL),c4 AS MATERIALIZED (SELECT * FROM (SELECT rel_path, line, item_key, source_version, namespace FROM facts WHERE predicate = 'fixture.name' AND instr(gilune_fold(value), 'al') = 1 AND line IS NULL AND item_key IS NULL) WHERE namespace IN (SELECT value FROM json_each('["fixture"]')) AND line IS NULL AND item_key IS NULL),matched AS MATERIALIZED (SELECT u.rel_path,u.source_version,min(CASE WHEN (u.rel_path,u.source_version) IN (SELECT rel_path,source_version FROM c2) THEN 0 ELSE 4294967296 END,CASE WHEN (u.rel_path,u.source_version) IN (SELECT rel_path,source_version FROM c3) THEN 1 ELSE 4294967296 END,CASE WHEN (u.rel_path,u.source_version) IN (SELECT rel_path,source_version FROM c4) THEN 2 ELSE 4294967296 END) AS priority FROM source_maps u WHERE (u.rel_path,u.source_version) IN (SELECT rel_path,source_version FROM c1) AND EXISTS (SELECT 1 FROM fact_sources r WHERE r.rel_path=u.rel_path AND r.source_version=u.source_version AND r.namespace='fixture')),sort_values AS MATERIALIZED (SELECT rel_path,source_version,MIN(CASE WHEN predicate='fixture.name' THEN value END) AS s0,MIN(CASE WHEN predicate='fixture.key' THEN value END) AS s1 FROM allowed GROUP BY rel_path,source_version),ranked AS (SELECT m.*,s.s0,s.s1 FROM matched m LEFT JOIN sort_values s ON s.rel_path=m.rel_path AND s.source_version=m.source_version) SELECT rel_path,source_version,priority,COUNT(*) OVER() FROM ranked WHERE priority < 4294967296 ORDER BY priority,s0 IS NULL,s0,s1 IS NULL,s1,rel_path LIMIT 30 OFFSET 0